using CounterStrikeSharp.API;
using CounterStrikeSharp.API.Core;
using CounterStrikeSharp.API.Modules.Extensions; // SetHasClassForPlayer / SetDialogVariableStringForPlayer (C# 14 extension members)
using Microsoft.Extensions.Logging;

namespace BlockingZones;

// The "bz" panorama (Content-addonmanager/panorama, generated by tools/gen_layout.py).
// The plugin owns its own custom_hud_layout entity, next to the one of PMM (same way as PMM_BuyMenu).
// The server can only write dialog variables and toggle classes per player; everything here is a cache of
// what was sent, so only changes go over the network.
public partial class BlockingZonesPlugin
{
    internal const string RootMenu = "bz-menu";
    internal const string RootPrev = "bz-prev";
    internal const string RootNote = "bz-note";
    internal const string Hidden = "bz-hidden";
    internal const int MenuRows = 8; // tools/gen_layout.py ROWS

    private CCSCustomHudLayout? _layout;
    private readonly HudSlot[] _hud = Enumerable.Range(0, 64).Select(_ => new HudSlot()).ToArray();
    private bool _force;

    private sealed class HudSlot
    {
        public readonly Dictionary<string, HashSet<string>> Classes = new();
        public readonly Dictionary<string, string> Vars = new();
        public int NoteToken;
        public readonly int[] RowHitToken = new int[MenuRows];
        public readonly int[] KeyHitToken = new int[10];

        // What the layout has as authored: the cache starts from that, not from "nothing".
        public void Reset()
        {
            Classes.Clear();
            Vars.Clear();
            Add(RootMenu, Hidden);
            Add(RootPrev, Hidden);
            Add(RootNote, Hidden);
            Add("bz-card", "c-off");
            Add("bz-now", "c-off");
            Add("bz-p-state", "p-ok");
            Add("bz-n-ladder", "lv-0");
            for (int i = 0; i < MenuRows; i++)
            {
                Add($"bz-r{i}", "r-off");
                Add($"bz-r{i}-bar", "b-0");
            }
        }

        private void Add(string panel, string cls)
        {
            if (!Classes.TryGetValue(panel, out var set)) Classes[panel] = set = new HashSet<string>();
            set.Add(cls);
        }
    }

    // ---------------- entity ----------------

    private bool EnsureLayout()
    {
        if (_layout is { IsValid: true }) return true;

        foreach (var s in _hud) s.Reset();
        try
        {
            var e = Utilities.CreateEntityByName<CCSCustomHudLayout>("custom_hud_layout");
            if (e == null || e.Handle == IntPtr.Zero)
            {
                Logger.LogWarning("custom_hud_layout could not be created");
                return false;
            }
            e.StrLayout = Cfg.LayoutPath;
            e.DispatchSpawn();
            if (!e.IsValid) return false;
            _layout = e;
            Logger.LogInformation("custom_hud_layout created: {Path}", Cfg.LayoutPath);
        }
        catch (Exception ex)
        {
            Logger.LogError("custom_hud_layout failed: {Error}", ex.Message);
            return false;
        }

        // A round restart removes the entity: whoever had the menu or the preview open gets it back.
        Server.NextFrame(RedrawAll);
        return true;
    }

    private void ForgetLayout()
    {
        _layout = null;
        foreach (var s in _hud) s.Reset();
    }

    private void RemoveOrphanLayouts()
    {
        try
        {
            foreach (var e in Utilities.FindAllEntitiesByDesignerName<CCSCustomHudLayout>("custom_hud_layout").ToList())
                if (e.IsValid && string.Equals(e.StrLayout, Cfg.LayoutPath, StringComparison.OrdinalIgnoreCase))
                    e.Remove();
        }
        catch (Exception ex)
        {
            Logger.LogWarning("Orphan layout cleanup failed: {Error}", ex.Message);
        }
    }

    private void KillLayout()
    {
        try
        {
            if (_layout is { IsValid: true }) _layout.Remove();
        }
        catch
        {
            // already gone
        }
        _layout = null;
    }

    private void RedrawAll()
    {
        if (_layout is not { IsValid: true }) return;
        foreach (var p in Utilities.GetPlayers())
        {
            if (p is not { IsValid: true, IsBot: false } || p.Slot is < 0 or >= 64) continue;
            if (_previews.TryGetValue(p.Slot, out var pv)) DrawPreview(p, pv);
            else if (_views[p.Slot] != null) Render(p);
        }
    }

    // A slot keeps the per-player overlay of its previous occupant: write the authored state for real.
    private void ResetPlayerHud(CCSPlayerController player)
    {
        if (player.Slot is < 0 or >= 64 || _layout is not { IsValid: true }) return;
        var st = _hud[player.Slot];
        st.Reset();
        _force = true;
        try
        {
            foreach (var (panel, set) in st.Classes.ToList())
                foreach (string cls in set.ToList())
                    SetClass(player, panel, cls, true);

            // and everything the previous occupant may have switched on
            for (int i = 0; i < MenuRows; i++)
            {
                foreach (string cls in new[] { "r-sel", "r-hit", "r-danger", "r-acc", "r-bar", "n-chip", "n-warn", "n-val" })
                    SetClass(player, $"bz-r{i}", cls, false);
                for (int b = 1; b <= 10; b++) SetClass(player, $"bz-r{i}-bar", "b-" + b, false);
            }
            SetClass(player, "bz-status", "s-ok", false);
            SetClass(player, "bz-status", "s-err", false);
            SetClass(player, "bz-nav8", "c-off", false);
            SetClass(player, "bz-p-state", "p-bad", false);
            foreach (int k in new[] { 1, 2, 3, 4, 5, 0 }) SetClass(player, $"bz-pk{k}", "k-hit", false);
            for (int lv = 1; lv <= 10; lv++) SetClass(player, "bz-n-ladder", "lv-" + lv, false);
            SetClass(player, RootNote, "n-show", false);
            SetClass(player, "bz-n-timer-fill", "t-run", false);
        }
        finally
        {
            _force = false;
        }
    }

    // ---------------- primitives ----------------

    internal void SetClass(CCSPlayerController player, string panel, string cls, bool on)
    {
        if (_layout is not { IsValid: true } || player.Slot is < 0 or >= 64) return;
        var st = _hud[player.Slot];
        if (!st.Classes.TryGetValue(panel, out var set)) st.Classes[panel] = set = new HashSet<string>();
        if (set.Contains(cls) == on && !_force) return;
        if (on) set.Add(cls);
        else set.Remove(cls);
        _layout.SetHasClassForPlayer(player, panel, cls, on);
    }

    // Exactly one class starting with prefix on the panel.
    internal void SetOnly(CCSPlayerController player, string panel, string cls, string prefix)
    {
        if (player.Slot is < 0 or >= 64) return;
        if (_hud[player.Slot].Classes.TryGetValue(panel, out var set))
            foreach (string other in set.Where(c => c != cls && c.StartsWith(prefix)).ToList())
                SetClass(player, panel, other, false);
        SetClass(player, panel, cls, true);
    }

    internal void SetVar(CCSPlayerController player, string panel, string name, string value)
    {
        if (_layout is not { IsValid: true } || player.Slot is < 0 or >= 64) return;
        var st = _hud[player.Slot];
        string key = panel + "|" + name;
        if (st.Vars.TryGetValue(key, out var old) && old == value && !_force) return;
        st.Vars[key] = value;
        // The client looks a value that is one bare word up in its own localization: "Back" came out as
        // "Сзади" (a map callout token) on a Russian client. A trailing no-break space stops the lookup.
        if (value.Length > 0 && value.All(ch => ch < 128 && (char.IsLetterOrDigit(ch) || ch == '_'))) value += "\u00A0";
        _layout.SetDialogVariableStringForPlayer(player, panel, name, value);
    }

    internal void ShowRoot(CCSPlayerController player, string root, bool show)
    {
        if (show && !EnsureLayout()) return;
        SetClass(player, root, Hidden, !show);
    }

    // Short highlight of the row / key the player just pressed (class on, off 0.35 s later - off and on
    // in the same tick would send nothing).
    private void FlashRow(CCSPlayerController player, int row)
    {
        if (row is < 0 or >= MenuRows || player.Slot is < 0 or >= 64) return;
        var st = _hud[player.Slot];
        int token = ++st.RowHitToken[row];
        SetClass(player, $"bz-r{row}", "r-hit", true);
        AddTimer(0.35f, () =>
        {
            if (player.IsValid && st.RowHitToken[row] == token) SetClass(player, $"bz-r{row}", "r-hit", false);
        });
    }

    private void FlashPreviewKey(CCSPlayerController player, int digit)
    {
        if (digit is < 0 or > 9 || player.Slot is < 0 or >= 64) return;
        var st = _hud[player.Slot];
        int token = ++st.KeyHitToken[digit];
        SetClass(player, $"bz-pk{digit}", "k-hit", true);
        AddTimer(0.35f, () =>
        {
            if (player.IsValid && st.KeyHitToken[digit] == token) SetClass(player, $"bz-pk{digit}", "k-hit", false);
        });
    }

    // ---------------- menu drawing ----------------

    internal enum NoteStyle { Plain, Chip, Warn, Value }

    internal sealed class MenuRow
    {
        public int Key;
        public string Text = "";
        public string Note = "";
        public NoteStyle Style;
        public bool Selected, Danger, Accent;
        public int Bar = -1; // 0..10 shows the mini bar
    }

    internal sealed class MenuModel
    {
        public string Title = "";
        public string Sub = "";
        public (string Num, string Name, string Info)? Card;
        public (string Cap, string Value)? Now;
        public readonly List<MenuRow> Rows = new();
        public string? Back; // label of key 8, null = hidden
        public string Close = "";
        public string Status = "";
        public int StatusKind; // 0 hint, 1 ok, 2 error
    }

    private void DrawMenu(CCSPlayerController player, MenuModel m)
    {
        if (!EnsureLayout()) return;

        SetVar(player, "bz-title", "title", m.Title);
        SetVar(player, "bz-sub", "sub", m.Sub);

        if (m.Card is { } card)
        {
            SetVar(player, "bz-card-num", "cardnum", card.Num);
            SetVar(player, "bz-card-name", "cardname", card.Name);
            SetVar(player, "bz-card-info", "cardinfo", card.Info);
        }
        SetClass(player, "bz-card", "c-off", m.Card == null);

        if (m.Now is { } now)
        {
            SetVar(player, "bz-now-cap", "nowcap", now.Cap);
            SetVar(player, "bz-now-val", "nowval", now.Value);
        }
        SetClass(player, "bz-now", "c-off", m.Now == null);

        for (int i = 0; i < MenuRows; i++)
        {
            string id = $"bz-r{i}";
            if (i >= m.Rows.Count)
            {
                SetClass(player, id, "r-off", true);
                continue;
            }

            var r = m.Rows[i];
            SetVar(player, id + "-k", $"r{i}k", r.Key.ToString());
            SetVar(player, id + "-t", $"r{i}t", r.Text);
            SetVar(player, id + "-n", $"r{i}n", r.Note);
            SetClass(player, id, "r-sel", r.Selected);
            SetClass(player, id, "r-danger", r.Danger);
            SetClass(player, id, "r-acc", r.Accent);
            SetClass(player, id, "n-chip", r.Style == NoteStyle.Chip);
            SetClass(player, id, "n-warn", r.Style == NoteStyle.Warn);
            SetClass(player, id, "n-val", r.Style == NoteStyle.Value);
            SetClass(player, id, "r-bar", r.Bar >= 0);
            if (r.Bar >= 0) SetOnly(player, id + "-bar", "b-" + Math.Clamp(r.Bar, 0, 10), "b-");
            SetClass(player, id, "r-off", false);
        }

        if (m.Back != null) SetVar(player, "bz-nav8-t", "nav8", m.Back);
        SetClass(player, "bz-nav8", "c-off", m.Back == null);
        SetVar(player, "bz-nav0-t", "nav0", m.Close);

        SetVar(player, "bz-status", "status", m.Status);
        SetClass(player, "bz-status", "s-ok", m.StatusKind == 1);
        SetClass(player, "bz-status", "s-err", m.StatusKind == 2);

        SetClass(player, RootPrev, Hidden, true);
        SetClass(player, RootMenu, Hidden, false);
    }
}
